/// Submit a new document processing job
#[reducer]
pub fn create_document_processing_job(
    ctx: &ReducerContext,
    organization_id: u64,
    company_id: Option<u64>,
    params: CreateDocumentProcessingJobParams,
) -> Result<(), String> {
    check_permission(ctx, organization_id, "ai_document_processing_job", "create")?;
    let operating_company_id = company_id_from_scope(ctx, organization_id, company_id)?;
    let stored_company_id = Some(operating_company_id);

    if let Some(doc_id) = params.document_id {
        let doc = ctx
            .db
            .document()
            .id()
            .find(&doc_id)
            .ok_or("Linked document not found")?;
        if doc.organization_id != organization_id {
            return Err("Linked document does not belong to this organization".to_string());
        }
        if let Some(ver_id) = params.document_version_id {
            let ver = ctx
                .db
                .document_version()
                .id()
                .find(&ver_id)
                .ok_or("Linked document version not found")?;
            if ver.document_id != doc_id || ver.organization_id != organization_id {
                return Err("document_version_id does not match document".to_string());
            }
        }
    }

    let job = ctx
        .db
        .ai_document_processing_job()
        .insert(AiDocumentProcessingJob {
            id: 0,
            organization_id,
            document_type: params.document_type,
            job_type: params.job_type,
            // System-managed: new jobs always start as Pending
            status: JobStatus::Pending,
            ai_agent_id: params.ai_agent_id,
            input_data: params.input_data,
            // System-managed: populated by complete_document_processing_job
            model_used: None,
            extracted_data: None,
            confidence_score: None,
            error_message: None,
            processing_started_at: None,
            processing_completed_at: None,
            tokens_used: None,
            cost: None,
            reviewed_by: None,
            reviewed_at: None,
            // System-managed: set to true only via approve_document_processing_job
            is_approved: false,
            document_id: params.document_id,
            document_version_id: params.document_version_id,
            company_id: stored_company_id,
            create_uid: ctx.sender(),
            create_date: ctx.timestamp,
            write_uid: ctx.sender(),
            write_date: ctx.timestamp,
            metadata: params.metadata,
        });

    write_audit_log_v2(
        ctx,
        organization_id,
        AuditLogParams {
            company_id: stored_company_id,
            table_name: "ai_document_processing_job",
            record_id: job.id,
            action: "create",
            old_values: None,
            new_values: None,
            changed_fields: vec!["submitted".to_string()],
            metadata: None,
        },
    );

    log::info!(
        "Document processing job created: id={}, type={}/{}",
        job.id,
        job.document_type,
        job.job_type
    );
    Ok(())
}

/// Update the result of a document processing job
#[reducer]
pub fn complete_document_processing_job(
    ctx: &ReducerContext,
    organization_id: u64,
    company_id: Option<u64>,
    job_id: u64,
    params: CompleteDocumentProcessingJobParams,
) -> Result<(), String> {
    check_permission(ctx, organization_id, "ai_document_processing_job", "write")?;
    if let Some(scope_company_id) = company_id {
        require_company_in_organization(ctx, organization_id, scope_company_id)?;
    }

    let job = ctx
        .db
        .ai_document_processing_job()
        .id()
        .find(&job_id)
        .ok_or("Processing job not found")?;

    ensure_doc_job_in_org(organization_id, job.organization_id)?;
    if let (Some(scope_company_id), Some(row_company_id)) = (company_id, job.company_id) {
        if scope_company_id != row_company_id {
            return Err("company_id does not match processing job scope".to_string());
        }
    }

    // status is computed: Failed if error_message present, else Completed
    let status = if params.error_message.is_some() {
        JobStatus::Failed
    } else {
        JobStatus::Completed
    };

    ctx.db
        .ai_document_processing_job()
        .id()
        .update(AiDocumentProcessingJob {
            status,
            extracted_data: params.extracted_data,
            confidence_score: params.confidence_score,
            model_used: params.model_used,
            tokens_used: params.tokens_used,
            cost: params.cost,
            error_message: params.error_message,
            processing_completed_at: Some(ctx.timestamp),
            write_uid: ctx.sender(),
            write_date: ctx.timestamp,
            ..job
        });

    write_audit_log_v2(
        ctx,
        organization_id,
        AuditLogParams {
            company_id: job.company_id,
            table_name: "ai_document_processing_job",
            record_id: job_id,
            action: "write",
            old_values: None,
            new_values: None,
            changed_fields: vec!["completed".to_string()],
            metadata: None,
        },
    );

    log::info!("Document processing job completed: id={}", job_id);
    Ok(())
}

/// Approve extracted data from a processing job
#[reducer]
pub fn approve_document_processing_job(
    ctx: &ReducerContext,
    organization_id: u64,
    company_id: Option<u64>,
    job_id: u64,
) -> Result<(), String> {
    check_permission(ctx, organization_id, "ai_document_processing_job", "write")?;
    if let Some(scope_company_id) = company_id {
        require_company_in_organization(ctx, organization_id, scope_company_id)?;
    }

    let job = ctx
        .db
        .ai_document_processing_job()
        .id()
        .find(&job_id)
        .ok_or("Processing job not found")?;

    ensure_doc_job_in_org(organization_id, job.organization_id)?;
    if let (Some(scope_company_id), Some(row_company_id)) = (company_id, job.company_id) {
        if scope_company_id != row_company_id {
            return Err("company_id does not match processing job scope".to_string());
        }
    }

    if job.status != JobStatus::Completed {
        return Err("Job must be completed before approval".to_string());
    }

    // Promote approved OCR / extraction into canonical evidence passages. The
    // processing job keeps the full result only while it is awaiting review.
    let mut indexed_document_id = None;
    let mut canonical_evidence = None;
    if let Some(doc_id) = job.document_id {
        if let Some(extracted) = job.extracted_data.as_ref() {
            let content = extracted.trim().to_string();
            if !content.is_empty() {
                if let Some(doc) = ctx.db.document().id().find(&doc_id) {
                    if doc.organization_id == organization_id && !doc.is_deleted {
                        let current_version_id = doc
                            .current_version_id
                            .ok_or("linked document has no current server-owned version")?;
                        if job
                            .document_version_id
                            .is_some_and(|version_id| version_id != current_version_id)
                        {
                            return Err(
                                "processing job targets a stale document version".to_string()
                            );
                        }
                        let version = ctx
                            .db
                            .document_version()
                            .id()
                            .find(&current_version_id)
                            .ok_or("current document version not found")?;
                        if version.document_id != doc_id || !version.is_current {
                            return Err(
                                "document version is not the current server-owned blob".to_string()
                            );
                        }
                        let language = document_search_language_for_company(
                            ctx,
                            organization_id,
                            doc.company_id,
                        );
                        let mut meta = doc.metadata.clone();
                        let doc_type = job.document_type.to_ascii_lowercase();
                        if doc_type.contains("invoice")
                            || doc_type.contains("receipt")
                            || doc_type.contains("expense")
                            || doc_type.contains("bill")
                        {
                            let approved_for = serde_json::json!({
                                "approved_extraction_for": ["expenses", "ap"],
                                "processing_job_id": job_id,
                            });
                            meta = Some(match meta {
                                Some(existing) => {
                                    if let Ok(mut v) =
                                        serde_json::from_str::<serde_json::Value>(&existing)
                                    {
                                        if let Some(obj) = v.as_object_mut() {
                                            obj.insert(
                                                "approved_extraction".to_string(),
                                                approved_for,
                                            );
                                            v.to_string()
                                        } else {
                                            approved_for.to_string()
                                        }
                                    } else {
                                        approved_for.to_string()
                                    }
                                }
                                None => approved_for.to_string(),
                            });
                        }
                        ctx.db.document().id().update(Document {
                            index_language: language.or(doc.index_language.clone()),
                            metadata: meta,
                            write_uid: ctx.sender(),
                            write_date: ctx.timestamp,
                            ..doc.clone()
                        });
                        let company_id = doc
                            .company_id
                            .ok_or("governed document evidence requires company scope")?;
                        let (source_version_id, passage_count) =
                            crate::ai::evidence_source::ingest_document_blob_content(
                                ctx,
                                organization_id,
                                company_id,
                                doc_id,
                                &doc.name,
                                version.version_number,
                                &version.url,
                                version.checksum.as_deref(),
                                &content,
                                "inspected",
                            )?;
                        let source_kind = "document".to_string();
                        let source_key = format!("document:{doc_id}");
                        let passages: Vec<_> = ctx
                            .db
                            .ai_evidence_passage()
                            .ai_evidence_passage_by_source()
                            .filter((&organization_id, &company_id, &source_kind, &source_key))
                            .filter(|passage| passage.source_version_id == Some(source_version_id))
                            .collect();
                        for passage in passages {
                            let params = UpsertSearchEmbeddingParams {
                                content_type: "ai_evidence_passage".to_string(),
                                content_id: passage.id,
                                expected_fingerprint: passage.content_hash.clone(),
                                index_generation: "semantic-index-v1".to_string(),
                                metadata: Some(
                                    serde_json::json!({
                                        "sourceKind": &passage.source_kind,
                                        "sourceKey": &passage.source_key,
                                        "sourceVersion": &passage.source_version,
                                        "passageKey": &passage.passage_key,
                                    })
                                    .to_string(),
                                ),
                            };
                            upsert_search_embedding_inner(
                                ctx,
                                organization_id,
                                company_id,
                                params,
                            )?;
                            request_embedding_job_inner(
                                ctx,
                                organization_id,
                                company_id,
                                "ai_evidence_passage",
                                passage.id,
                                &passage.content_hash,
                                "semantic-index-v1",
                            )?;
                        }
                        canonical_evidence = Some((source_version_id, passage_count));
                        indexed_document_id = Some(doc_id);
                    }
                }
            }
        }
    }

    let job_company_id = job.company_id;
    let extracted_data = if canonical_evidence.is_some() {
        None
    } else {
        job.extracted_data.clone()
    };
    let job_metadata = canonical_evidence.map_or_else(
        || job.metadata.clone(),
        |(source_version_id, passage_count)| {
            let mut metadata = job
                .metadata
                .as_deref()
                .and_then(|value| serde_json::from_str::<serde_json::Value>(value).ok())
                .filter(serde_json::Value::is_object)
                .unwrap_or_else(|| serde_json::json!({}));
            if let Some(object) = metadata.as_object_mut() {
                object.insert(
                    "canonicalEvidence".to_string(),
                    serde_json::json!({
                        "sourceVersionId": source_version_id,
                        "passageCount": passage_count,
                    }),
                );
            }
            Some(metadata.to_string())
        },
    );
    ctx.db
        .ai_document_processing_job()
        .id()
        .update(AiDocumentProcessingJob {
            is_approved: true,
            extracted_data,
            reviewed_by: Some(ctx.sender()),
            reviewed_at: Some(ctx.timestamp),
            metadata: job_metadata,
            write_uid: ctx.sender(),
            write_date: ctx.timestamp,
            ..job
        });

    write_audit_log_v2(
        ctx,
        organization_id,
        AuditLogParams {
            company_id: job_company_id,
            table_name: "ai_document_processing_job",
            record_id: job_id,
            action: "write",
            old_values: None,
            new_values: None,
            changed_fields: vec!["approved".to_string()],
            metadata: None,
        },
    );

    let committed_job = ctx
        .db
        .ai_document_processing_job()
        .id()
        .find(&job_id)
        .ok_or("Processing job disappeared before commit recording")?;
    let mut changes = Vec::new();
    if let Some(document_id) = indexed_document_id {
        let committed_document = ctx
            .db
            .document()
            .id()
            .find(&document_id)
            .ok_or("Indexed document disappeared before commit recording")?;
        changes.push(RowChange::upsert_stdb_row(
            "document",
            serde_json::json!({"id": committed_document.id}),
            &committed_document,
        )?);
    }
    changes.push(RowChange::upsert_stdb_row(
        "ai_document_processing_job",
        serde_json::json!({"id": committed_job.id}),
        &committed_job,
    )?);
    record_organization_commit(
        ctx,
        OrganizationCommitInput {
            organization_id,
            operation_id: "erp.approve_document_processing_job".to_string(),
            correlation_id: format!("document-processing-job:{job_id}:approve"),
            changes,
        },
    )?;

    log::info!("Document processing job approved: id={}", job_id);
    Ok(())
}

/// Upsert a search embedding for a piece of content
#[reducer]
pub fn upsert_search_embedding(
    ctx: &ReducerContext,
    organization_id: u64,
    company_id: Option<u64>,
    params: UpsertSearchEmbeddingParams,
) -> Result<(), String> {
    check_permission(ctx, organization_id, "search_embedding", "create")?;
    let operating_company_id = company_id_from_scope(ctx, organization_id, company_id)?;
    upsert_search_embedding_inner(ctx, organization_id, operating_company_id, params)
}

fn upsert_search_embedding_inner(
    ctx: &ReducerContext,
    organization_id: u64,
    operating_company_id: u64,
    params: UpsertSearchEmbeddingParams,
) -> Result<(), String> {
    if params.index_generation.trim().is_empty() {
        return Err("index_generation must not be empty".to_string());
    }
    require_current_passage(
        ctx,
        organization_id,
        operating_company_id,
        &params.content_type,
        params.content_id,
        &params.expected_fingerprint,
    )?;
    let stored_company_id = Some(operating_company_id);

    // Check if an embedding already exists for this content
    let existing: Option<SearchEmbedding> = ctx
        .db
        .search_embedding()
        .embedding_by_content()
        .filter(&params.content_type)
        .find(|e| e.content_id == params.content_id && e.company_id == stored_company_id);

    if let Some(existing) = existing {
        ensure_embedding_in_org(organization_id, existing.organization_id)?;
        if existing.expected_fingerprint == params.expected_fingerprint
            && existing.index_generation == params.index_generation
            && existing.sync_status == "synced"
        {
            return Ok(());
        }
        // Reset sync_status to "pending" so the gateway re-indexes the updated content
        ctx.db.search_embedding().id().update(SearchEmbedding {
            expected_fingerprint: params.expected_fingerprint,
            index_generation: params.index_generation,
            sync_status: "pending".to_string(),
            vector_db_id: None,
            embedding_model: None,
            embedding_dim: None,
            last_synced_at: None,
            sync_error: None,
            write_uid: ctx.sender(),
            write_date: ctx.timestamp,
            metadata: params.metadata,
            ..existing
        });
        log::info!(
            "Search embedding updated: content_type={}, content_id={}",
            params.content_type,
            params.content_id
        );
    } else {
        ctx.db.search_embedding().insert(SearchEmbedding {
            id: 0,
            organization_id,
            content_type: params.content_type.clone(),
            content_id: params.content_id,
            expected_fingerprint: params.expected_fingerprint,
            index_generation: params.index_generation,
            sync_status: "pending".to_string(),
            vector_db_id: None,
            embedding_model: None,
            embedding_dim: None,
            last_synced_at: None,
            sync_error: None,
            company_id: stored_company_id,
            create_uid: ctx.sender(),
            create_date: ctx.timestamp,
            write_uid: ctx.sender(),
            write_date: ctx.timestamp,
            metadata: params.metadata,
        });
        log::info!(
            "Search embedding created: content_type={}, content_id={}",
            params.content_type,
            params.content_id
        );
    }

    Ok(())
}

/// Called by the AI Gateway after a vector has been successfully upserted into Qdrant.
/// Updates sync metadata so clients and workers can track indexing state.
#[reducer]
pub fn mark_embedding_synced(
    ctx: &ReducerContext,
    organization_id: u64,
    company_id: Option<u64>,
    embedding_id: u64,
    model: String,
    dim: u32,
) -> Result<(), String> {
    check_permission(ctx, organization_id, "search_embedding", "write")?;
    if let Some(scope_company_id) = company_id {
        require_company_in_organization(ctx, organization_id, scope_company_id)?;
    }

    let existing = ctx
        .db
        .search_embedding()
        .id()
        .find(&embedding_id)
        .ok_or("Embedding not found")?;

    ensure_embedding_in_org(organization_id, existing.organization_id)?;
    if let (Some(scope_company_id), Some(row_company_id)) = (company_id, existing.company_id) {
        if scope_company_id != row_company_id {
            return Err("company_id does not match embedding scope".to_string());
        }
    }

    ctx.db.search_embedding().id().update(SearchEmbedding {
        sync_status: "synced".to_string(),
        vector_db_id: Some(embedding_id.to_string()),
        embedding_model: Some(model),
        embedding_dim: Some(dim),
        last_synced_at: Some(ctx.timestamp),
        sync_error: None,
        write_uid: ctx.sender(),
        write_date: ctx.timestamp,
        ..existing
    });

    log::info!("Search embedding synced to vector DB: id={}", embedding_id);
    Ok(())
}

/// Atomically finalize a successful external-index upsert and its leased job.
#[reducer]
pub fn finalize_embedding_job(
    ctx: &ReducerContext,
    organization_id: u64,
    company_id: Option<u64>,
    embedding_id: u64,
    model: String,
    dim: u32,
    job_id: u64,
    params: CompleteQueueJobParams,
) -> Result<(), String> {
    check_permission(ctx, organization_id, "search_embedding", "write")?;
    let operating_company_id = company_id_from_scope(ctx, organization_id, company_id)?;
    if params.outcome != QueueCompletionOutcome::Succeeded {
        return Err("embedding finalization requires a successful job outcome".to_string());
    }

    let embedding = ctx
        .db
        .search_embedding()
        .id()
        .find(&embedding_id)
        .ok_or("embedding not found")?;
    ensure_embedding_in_org(organization_id, embedding.organization_id)?;
    if embedding.company_id != Some(operating_company_id) {
        return Err("company_id does not match embedding scope".to_string());
    }
    if params.response_fingerprint.as_deref() != Some(embedding.expected_fingerprint.as_str()) {
        return Err("response_fingerprint does not match canonical passage".to_string());
    }

    let job = ctx
        .db
        .queue_job()
        .id()
        .find(&job_id)
        .ok_or("embedding queue job not found")?;
    if job.organization_id != organization_id
        || job.company_id != Some(operating_company_id)
        || job.queue_name != "embedding"
        || job.job_type != "embed_content"
    {
        return Err("queue job does not match embedding scope".to_string());
    }
    require_queue_job_worker_authority(ctx, organization_id, &job.queue_name)?;

    let expected_semantic_key = format!(
        "embedding:{}:{}:{}:{}",
        embedding.content_type,
        embedding.content_id,
        embedding.expected_fingerprint,
        embedding.index_generation,
    );
    if job.status == QueueJobStatus::Completed && embedding.sync_status == "synced" {
        let expected_vector_db_id = embedding_id.to_string();
        if job.semantic_key != expected_semantic_key
            || embedding.vector_db_id.as_deref() != Some(expected_vector_db_id.as_str())
            || embedding.embedding_model.as_deref() != Some(model.as_str())
            || embedding.embedding_dim != Some(dim)
        {
            return Err("completed embedding finalization replay does not match".to_string());
        }
        return complete_queue_job_inner(ctx, organization_id, job_id, params);
    }
    if job.status != QueueJobStatus::Leased || embedding.sync_status != "pending" {
        return Err("embedding and queue job are not pending finalization".to_string());
    }

    let payload: serde_json::Value = serde_json::from_str(&job.payload)
        .map_err(|error| format!("invalid embedding job payload: {error}"))?;
    let payload_matches = payload.get("operation").and_then(serde_json::Value::as_str)
        == Some("upsert")
        && payload
            .get("company_id")
            .and_then(serde_json::Value::as_u64)
            == Some(operating_company_id)
        && payload
            .get("content_type")
            .and_then(serde_json::Value::as_str)
            == Some(embedding.content_type.as_str())
        && payload
            .get("content_id")
            .and_then(serde_json::Value::as_u64)
            == Some(embedding.content_id)
        && payload
            .get("expected_fingerprint")
            .and_then(serde_json::Value::as_str)
            == Some(embedding.expected_fingerprint.as_str())
        && payload
            .get("index_generation")
            .and_then(serde_json::Value::as_str)
            == Some(embedding.index_generation.as_str())
        && job.semantic_key == expected_semantic_key;
    if !payload_matches {
        return Err("leased queue job does not match embedding state".to_string());
    }
    ctx.db.search_embedding().id().update(SearchEmbedding {
        sync_status: "synced".to_string(),
        vector_db_id: Some(embedding_id.to_string()),
        embedding_model: Some(model),
        embedding_dim: Some(dim),
        last_synced_at: Some(ctx.timestamp),
        sync_error: None,
        write_uid: ctx.sender(),
        write_date: ctx.timestamp,
        ..embedding
    });
    complete_queue_job_inner(ctx, organization_id, job_id, params)
}

/// Soft-delete a search embedding (marks as "deleted" so the AI Gateway removes it from Qdrant).
/// Preserves the row for audit trail.
#[reducer]
pub fn delete_search_embedding(
    ctx: &ReducerContext,
    organization_id: u64,
    company_id: Option<u64>,
    content_type: String,
    content_id: u64,
) -> Result<(), String> {
    check_permission(ctx, organization_id, "search_embedding", "delete")?;
    let operating_company_id = company_id_from_scope(ctx, organization_id, company_id)?;
    if !delete_search_embedding_inner(
        ctx,
        organization_id,
        operating_company_id,
        &content_type,
        content_id,
    )? {
        return Err("Embedding not found for this content".to_string());
    }
    Ok(())
}

pub(crate) fn delete_search_embedding_inner(
    ctx: &ReducerContext,
    organization_id: u64,
    operating_company_id: u64,
    content_type: &str,
    content_id: u64,
) -> Result<bool, String> {
    let stored_company_id = Some(operating_company_id);

    let Some(existing) = ctx
        .db
        .search_embedding()
        .embedding_by_content()
        .filter(content_type)
        .find(|e| e.content_id == content_id && e.company_id == stored_company_id)
    else {
        return Ok(false);
    };

    ensure_embedding_in_org(organization_id, existing.organization_id)?;

    let embedding_id = existing.id;
    let expected_fingerprint = existing.expected_fingerprint.clone();
    let index_generation = existing.index_generation.clone();
    ctx.db.search_embedding().id().update(SearchEmbedding {
        sync_status: "deleted".to_string(),
        write_uid: ctx.sender(),
        write_date: ctx.timestamp,
        ..existing
    });

    let payload = format!(
        r#"{{"operation":"delete","company_id":{},"content_type":{},"content_id":{},"expected_fingerprint":{},"index_generation":{}}}"#,
        operating_company_id,
        serde_json_escape(content_type),
        content_id,
        serde_json_escape(&expected_fingerprint),
        serde_json_escape(&index_generation),
    );
    enqueue_job_internal(
        ctx,
        organization_id,
        EnqueueJobParams {
            company_id: Some(operating_company_id),
            queue_name: "embedding".to_string(),
            job_type: "delete_embedding".to_string(),
            payload,
            semantic_key: format!(
                "embedding-delete:{content_type}:{content_id}:{expected_fingerprint}:{index_generation}:{embedding_id}"
            ),
            priority: 10,
            max_attempts: 3,
            available_at_micros: None,
            correlation_id: format!("embedding-delete:{content_type}:{content_id}"),
            causation_id: None,
            metadata: None,
        },
    )?;

    log::info!(
        "Search embedding marked for deletion: content_type={}, content_id={}",
        content_type,
        content_id
    );
    Ok(true)
}

/// Enqueue an embedding job for the AI Gateway worker to process.
/// Call this after creating or updating any ERP record that should be searchable.
/// The gateway polls the "embedding" queue, generates the vector, and calls mark_embedding_synced.
#[reducer]
pub fn request_embedding_job(
    ctx: &ReducerContext,
    organization_id: u64,
    company_id: Option<u64>,
    content_type: String,
    content_id: u64,
    expected_fingerprint: String,
    index_generation: String,
) -> Result<(), String> {
    check_permission(ctx, organization_id, "search_embedding", "create")?;
    let operating_company_id = company_id_from_scope(ctx, organization_id, company_id)?;
    request_embedding_job_inner(
        ctx,
        organization_id,
        operating_company_id,
        &content_type,
        content_id,
        &expected_fingerprint,
        &index_generation,
    )
}

fn request_embedding_job_inner(
    ctx: &ReducerContext,
    organization_id: u64,
    operating_company_id: u64,
    content_type: &str,
    content_id: u64,
    expected_fingerprint: &str,
    index_generation: &str,
) -> Result<(), String> {
    if index_generation.trim().is_empty() {
        return Err("index_generation must not be empty".to_string());
    }
    require_current_passage(
        ctx,
        organization_id,
        operating_company_id,
        content_type,
        content_id,
        expected_fingerprint,
    )?;

    let content_type_key = content_type.to_string();
    let embedding = ctx
        .db
        .search_embedding()
        .embedding_by_content()
        .filter(&content_type_key)
        .find(|row| row.content_id == content_id && row.company_id == Some(operating_company_id))
        .ok_or("search embedding state must exist before the job is requested")?;
    if embedding.organization_id != organization_id
        || embedding.expected_fingerprint != expected_fingerprint
        || embedding.index_generation != index_generation
    {
        return Err("search embedding state does not match the requested passage".to_string());
    }
    if embedding.sync_status == "synced" {
        return Ok(());
    }
    if embedding.sync_status != "pending" {
        return Err("search embedding state is not pending".to_string());
    }

    let payload = format!(
        r#"{{"operation":"upsert","company_id":{},"content_type":{},"content_id":{},"expected_fingerprint":{},"index_generation":{}}}"#,
        operating_company_id,
        serde_json_escape(content_type),
        content_id,
        serde_json_escape(expected_fingerprint),
        serde_json_escape(index_generation),
    );

    enqueue_job_internal(
        ctx,
        organization_id,
        EnqueueJobParams {
            company_id: Some(operating_company_id),
            queue_name: "embedding".to_string(),
            job_type: "embed_content".to_string(),
            payload,
            semantic_key: format!(
                "embedding:{content_type}:{content_id}:{expected_fingerprint}:{index_generation}"
            ),
            priority: 5,
            max_attempts: 3,
            available_at_micros: None,
            correlation_id: format!("embedding:{content_type}:{content_id}"),
            causation_id: None,
            metadata: None,
        },
    )?;

    log::info!(
        "Embedding job queued: content_type={}, content_id={}",
        content_type,
        content_id
    );
    Ok(())
}

/// Minimal JSON string escaping for embedding payloads (avoids pulling in serde_json).
fn serde_json_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}
